@Component("correctiveAction-handler")
@ProcessingGroup("correctiveAction-processing-group")
public class CorrectiveActionEventHandler {
	
	// core constructor
	CorrectiveActionEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCorrectiveActionEvent
     */
    @EventHandler
    public void handle( CreateCorrectiveActionEvent event) {
        entityManager.persist(new CorrectiveAction(event.getCorrectiveActionId(), event.getCapaNumber(), event.getRootCause(), event.getCorrectiveAction(), event.getVerificationDate(), event.getNonconformance(), event.getOwner(), event.getStatus()));
    }

    /*
     * @param	event UpdateCorrectiveActionEvent
     */
    @EventHandler
    public CorrectiveAction handle( UpdateCorrectiveActionEvent event) {
    	entityManager.merge(new CorrectiveAction(event.getCorrectiveActionId(), event.getCapaNumber(), event.getRootCause(), event.getCorrectiveAction(), event.getVerificationDate(), event.getNonconformance(), event.getOwner(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteCorrectiveActionEvent
     */
    @EventHandler
    public void on( DeleteCorrectiveActionEvent event) {
    	CorrectiveAction entity = new CorrectiveAction();
   
    	// ------------------------------------------
    	// apply the CorrectiveActionId
    	// ------------------------------------------
    	entity.setCorrectiveActionId( event.getCorrectiveActionId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CorrectiveActionRepository correctiveActionEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CorrectiveActionEventHandler.class.getName());

}
